$global:GENERIC_GLOSSARY['bind'] = 'Bind|Convert a quote (status=1) into an active policy (status=2). Payment is collected, coverage becomes effective. Triggers BindPolicy command -> bindquote-msg-queue -> MonitorQueues WebJob.|quote;endorse'
$global:GENERIC_GLOSSARY['endorse'] = 'Endorse|Mid-term policy change after binding. Examples: address change, coverage change, add mortgagee. Creates EndorsementScenario (status=13), then binds via bindendorsement-msg-queue.|bind'
$global:GENERIC_GLOSSARY['fnol'] = 'FNOL|First Notice of Loss. The initial report of a claim event by the insured. Triggers FNOL submission -> Snapsheet -> initiate-fnol-submission-msg-queue.|'
$global:GENERIC_GLOSSARY['cancel'] = 'Cancel|Terminate coverage before policy expiration. Types: non-pay cancel (NPC), company request cancel, insured request cancel. Routes through requestcancel-msg-queue or nonpaycancel-msg-queue.|nonpay_cancel;reinstate;nonrenewal'
$global:GENERIC_GLOSSARY['reinstate'] = 'Reinstate|Restore a cancelled policy. Only valid within reinstatement window. Routes through reinstatement-msg-queue.|cancel'
$global:GENERIC_GLOSSARY['renew'] = 'Renew|Issue a new policy term when current term expires. RenewalOffer WebJob creates the offer; Renewals WebJob processes the bind.|nonrenewal;bind'
$global:GENERIC_GLOSSARY['nonpay_cancel'] = 'Non-Pay Cancel|Cancellation triggered by missed payment. NonPayCancel WebJob + BillingNOP WebJob. Insured gets grace period before final cancel.|cancel;installment'
$global:GENERIC_GLOSSARY['rewrite'] = 'Rewrite|Cancel current policy and create a new one, typically for major changes or product migrations. Routes through rewrite-msg-queue.|cancel;bind'
$global:GENERIC_GLOSSARY['quote'] = 'Quote|A priced but unbound insurance application. Status=1. No coverage until bound. Expires if not bound.|bind;premium'
$global:GENERIC_GLOSSARY['premium'] = 'Premium|The price charged for insurance coverage. Calculated by RatingService using product-specific rate books.|deductible;installment;commission'
$global:GENERIC_GLOSSARY['deductible'] = 'Deductible|The amount the insured pays out-of-pocket before insurance pays. Part of the policy coverage terms.|premium'
$global:GENERIC_GLOSSARY['pje'] = 'PJE|Process Job Execution. The audit trail for every async background job. Visible at /Admin/ProcessJobExecution.|'
$global:GENERIC_GLOSSARY['acord'] = 'ACORD|Insurance data interchange standard. MSI uses ACORD XML for Widget<->API communication. AcordBM.cs is the 10k-line translation layer.|'
$global:GENERIC_GLOSSARY['master_policy'] = 'Master Policy|A community-level policy covering multiple units (apartment complex). Individual tenants get certificates underneath. MasterController handles this.|certificate;pmc'
$global:GENERIC_GLOSSARY['certificate'] = 'Certificate|An individual tenant''s coverage document under a master policy. Part of the GroupRenters product.|master_policy'
$global:GENERIC_GLOSSARY['surplus_lines'] = 'Surplus Lines|Insurance placed with non-admitted (E&S) carriers. Requires surplus lines tax reporting via InsCipher. HomeownersES products are surplus lines.|es;admitted'
$global:GENERIC_GLOSSARY['admitted'] = 'Admitted|Insurance placed with state-regulated carriers. HomeownersAdmitted products. More regulated than E&S.|surplus_lines;es'
$global:GENERIC_GLOSSARY['es'] = 'E&S|Excess & Surplus. Non-admitted insurance. Less regulated. HomeownersESHO3, HomeownersESHO5, HomeownersESMS, HomeownersESREI.|surplus_lines;admitted'
$global:GENERIC_GLOSSARY['pmc'] = 'PMC|Property Management Company. Manages apartment communities. GroupRenters and AppFolio integrations serve PMC clients.|master_policy;certificate'
$global:GENERIC_GLOSSARY['dta'] = 'DTA|Direct-to-Agent. A flood portal variant where the agent is the primary user.|dtc'
$global:GENERIC_GLOSSARY['dtc'] = 'DTC|Direct-to-Consumer. A flood portal variant where the end customer self-serves.|dta'
$global:GENERIC_GLOSSARY['moratorium'] = 'Moratorium|A geographic restriction on writing new policies, typically after a natural disaster. MoratoriumController + Moratorium WebJob.|'
$global:GENERIC_GLOSSARY['ofac'] = 'OFAC|Office of Foreign Assets Control. Sanctions screening on new policies. OFAC WebJob + commercial-ofac-validation-msg-queue.|'
$global:GENERIC_GLOSSARY['clue'] = 'CLUE|Comprehensive Loss Underwriting Exchange. LexisNexis integration that pulls prior claims history during underwriting.|'
$global:GENERIC_GLOSSARY['suspense'] = 'Suspense|A policy hold status (code=36) where automated processing is paused. ProcessSuspense WebJob resolves them.|'
$global:GENERIC_GLOSSARY['nonrenewal'] = 'Non-Renewal|Decision not to renew a policy at expiration. PendingNonRenewal -> NonRenewal WebJob -> nonrenewal-msg-queue.|renew;cancel'
$global:GENERIC_GLOSSARY['commission'] = 'Commission|Compensation paid to agents for written premium. CommissionService + AgencyCommissionDownload WebJob.|premium'
$global:GENERIC_GLOSSARY['installment'] = 'Installment|A payment plan where premium is paid in scheduled partial amounts. Installment WebJob processes scheduled charges.|premium;nonpay_cancel'
$global:GENERIC_GLOSSARY['econsent'] = 'eConsent|Electronic consent to receive policy documents via email instead of paper. EConsentNotification WebJob.|'
